type Section =
  | { kind: 'imageWithText'; imageField: string; textField: string }
  | { kind: 'linkList'; field: string }
  | { kind: 'facetedSearch'; facetsField: string; itemsField: string }
  | { kind: 'sectionList'; field: string }

type FacetedItem<T> = {
  id: string
  facets: Record<string, string[]>
  data: T
}

type FacetedDataset<T> = {
  facetDefinitions: { key: string; label: string; multiSelect?: boolean }[]
  items: FacetedItem<T>[]
}
